import React, { useState, useEffect } from 'react';
import { Box, Button, FormControl, FormLabel, Input, Textarea, VStack, useToast, Text } from '@chakra-ui/react';
import { api } from '../services/api';
import { Note } from '../types';

interface NoteEditorProps {
  note: Note | null;
  onFinishEdit: () => void;
}

export const NoteEditor: React.FC<NoteEditorProps> = ({ note, onFinishEdit }) => {
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [tags, setTags] = useState<string>('');
  const [summary, setSummary] = useState<string | undefined>('');
  const toast = useToast();

  useEffect(() => {
    if (note) {
      setTitle(note.title);
      setContent(note.content);
      setTags(note.tags ? note.tags.join(', ') : '');
      setSummary(note.summary);
    } else {
      setTitle('');
      setContent('');
      setTags('');
      setSummary('');
    }
  }, [note]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const tagsArray = tags.split(',').map(tag => tag.trim()).filter(tag => tag.length > 0);
    try {
      let result: Note;
      if (note) {
        result = await api.updateNote(note.id.toString(), { title, content, tags: tagsArray });
        toast({
          title: "Note updated",
          status: "success",
          duration: 3000,
          isClosable: true,
        });
      } else {
        result = await api.createNote({ title, content, tags: tagsArray });
        toast({
          title: "Note created",
          status: "success",
          duration: 3000,
          isClosable: true,
        });
      }
      setTitle('');
      setContent('');
      setTags('');
      setSummary(result.summary);
      onFinishEdit();
    } catch (error) {
      toast({
        title: "Error saving note",
        status: "error",
        duration: 3000,
        isClosable: true,
      });
    }
  };

  return (
    <Box as="form" onSubmit={handleSubmit}>
      <VStack spacing={4}>
        <FormControl>
          <FormLabel>Title</FormLabel>
          <Input
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="Note title"
          />
        </FormControl>
        <FormControl>
          <FormLabel>Content</FormLabel>
          <Textarea
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder="Write your note here..."
            rows={6}
          />
        </FormControl>
        <FormControl>
          <FormLabel>Tags (comma separated)</FormLabel>
          <Input
            value={tags}
            onChange={e => setTags(e.target.value)}
            placeholder="e.g. work, personal, urgent"
          />
        </FormControl>
        {summary && (
          <Text mt={2} fontStyle="italic" color="gray.600">
            Summary: {summary}
          </Text>
        )}
        <Button type="submit" colorScheme="blue">
          {note ? 'Update Note' : 'Save Note'}
        </Button>
      </VStack>
    </Box>
  );
};
